        {"title": "Q3 2026 financial review", "bullets": ["Halvorsen Group", "Finance team — Erik Halvorsen, CFO", "October 21, 2026"], "talk": ["So today I want to walk you through how the third quarter went for the group and what it means for the full year.", "Good morning everyone, I'll keep this to about twenty minutes and leave time at the end."]},
        {"title": "Agenda", "bullets": ["Headline numbers", "Revenue by segment", "Costs and cash", "Outlook"], "talk": ["I'll start with the headline numbers, then go segment by segment, then costs and cash, and finish with the outlook.", "So four parts, and questions at the end please."]},
        {"title": "Headline numbers", "bullets": ["Revenue EUR 142M, up 6% YoY", "EBITDA EUR 21.3M, 15.0% margin", "Net income EUR 9.8M"], "talk": ["Revenue came in at one hundred forty-two million euros, six percent ahead of last year's third quarter.", "EBITDA was 21.3 million, a fifteen percent margin, and net income just under ten million."]},
        {"title": "Revenue by segment", "bullets": ["Marine propulsion EUR 78M, +9%", "Deck equipment EUR 41M, +2%", "Service and parts EUR 23M, +5%"], "talk": ["Propulsion carried the quarter at seventy-eight million, up nine percent, mostly on ferry orders from Scandinavia.", "Deck equipment was basically flat at forty-one million, and service grew five percent to twenty-three."]},
