        {"title": "Agenda", "bullets": ["KPIs", "Wins and misses", "Hiring and cash", "Decisions needed"], "talk": ["We'll go through the KPIs first, then wins and misses, a short hiring and cash update, and the two decisions at the end.", "I've kept it to four sections so we have time for discussion."]},
        {"title": "KPIs", "bullets": ["ARR $8.4M, up 41% YoY", "Net revenue retention 118%", "Burn $410k per month"], "talk": ["Annual recurring revenue is at eight point four million dollars, up forty-one percent from a year ago.", "Net retention is a hundred and eighteen percent and we're burning about four hundred ten thousand a month."]},
        {"title": "Wins and misses", "bullets": ["Win: signed Deltair, $380k ACV", "Win: churn down to 1.1% monthly", "Miss: EU data center slipped 6 weeks"], "talk": ["The big one this quarter was signing Deltair at three hundred eighty thousand a year, our largest contract ever.", "On the downside, the EU data center slipped six weeks because the hosting provider was late."]},
        {"title": "Hiring", "bullets": ["Headcount 74, plan 80", "VP Sales starts April 7", "Engineering offer acceptance 70%"], "talk": ["We're at seventy-four people against a plan of eighty, so a bit behind.", "Good news is our new VP of Sales starts on April seventh."]},
        {"title": "Cash position", "bullets": ["Cash $9.6M", "Runway 23 months", "Break-even targeted Q3 2027"], "talk": ["We have 9.6 million dollars in the bank, which is about twenty-three months of runway.", "On the current plan we reach break-even in the third quarter of 2027."]},
        {"title": "Decisions needed", "bullets": ["Approve option pool top-up: 3%", "Approve $1.2M for EU expansion"], "talk": ["First, we need your approval to top up the option pool by three percent for this year's hires.", "Second, we're asking for one point two million dollars to properly staff the European launch."]},
